import{_ as t,o as r,c as s,a5 as a}from"./chunks/framework.CslsFoWx.js";const i="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/01-avant-reception-clavier-ouvert.webp",o="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/02-avant-plantage-et-reception-enregistree.webp",n="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/03-apres-reception-clavier-ouvert.webp",d="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/04-apres-reception-validee.webp",l="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/05-avant-prix-tronque.webp",c="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/06-apres-prix-entier-fr-en-ar.webp",p="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/07-apres-ecran-de-vente-en.webp",u="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/08-apres-planche-tuiles-langues-tailles.webp",m="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/09-avant-feuille-mode-mixte.webp",g="/VendoraSystem-docs/captures/2026-11-08-ios-reception-prix/10-apres-feuille-suit-en-direct.webp",q=JSON.parse('{"title":"Caisse iOS : réception validée clavier ouvert, prix des tuiles, feuilles en clair / sombre (08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-ios-reception-prix.md","filePath":"generated/preuves/2026-11-08-ios-reception-prix.md","lastUpdated":null}'),v={name:"preuves/2026-11-08-ios-reception-prix.md"};function f(h,e,b,x,P,_){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="caisse-ios-reception-validee-clavier-ouvert-prix-des-tuiles-feuilles-en-clair-sombre-08-11-2026" tabindex="-1">Caisse iOS : réception validée clavier ouvert, prix des tuiles, feuilles en clair / sombre (08/11/2026) <a class="header-anchor" href="#caisse-ios-reception-validee-clavier-ouvert-prix-des-tuiles-feuilles-en-clair-sombre-08-11-2026" aria-label="Permalink to &quot;Caisse iOS : réception validée clavier ouvert, prix des tuiles, feuilles en clair / sombre (08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-ios-reception-prix</code> · 0 image(s) · 0 trace(s)</p><div><p>Deux cartes Trello :</p><ul><li><strong>P2 · Caisse iOS : plantage en validant une réception fournisseur avec le clavier ouvert</strong> ;</li><li><strong>P3 · Caisse iOS en anglais : prix de « Formule midi » tronqué (« 19,9 »)</strong>, avec le reste de la même carte : « une fenêtre déjà ouverte ne change d&#39;apparence (clair / sombre) qu&#39;à sa réouverture ».</li></ul><p>Vraie stack : serveur de dev <code>:8080</code>, app iOS construite depuis le worktree sur un simulateur dédié (iPad Air 11&quot; M3, iOS 26.2, « Recep-iPad-ac87 », supprimé à la fin), pilote XCUITest <code>help/tools/mobile/pilote-ios</code>. Données fictives : « Épicerie Lumière (démo) » (<code>bistrot.demo+cap1108+epicerie@vendora.test</code>, responsable « Marc (responsable) », bons <code>PO-EPI-2026-0002</code> et <code>0003</code> créés par l&#39;API comme dans <code>help/tools/seed/seed-stock-caisse.py</code>) puis « Le Petit Bistrot (démo) » (<code>bistrot.demo+cap1108@vendora.test</code>, thème en SYSTEM). La version « avant » est l&#39;app de <code>HEAD</code> (avant correction) construite à part ; la version « après » est celle du lot.</p><h2 id="p2-·-reception-validee-avec-le-clavier-ouvert" tabindex="-1">P2 · Réception validée avec le clavier ouvert <a class="header-anchor" href="#p2-·-reception-validee-avec-le-clavier-ouvert" aria-label="Permalink to &quot;P2 · Réception validée avec le clavier ouvert&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+i+'" alt=""></td><td><strong>Avant</strong> : « Tout reçu », puis Cidre ramené à 4 dans le champ <strong>Reçu</strong> (1), clavier ouvert ; on touche <strong>Valider la réception</strong> (2) sans le fermer</td></tr><tr><td><img src="'+o+'" alt=""></td><td><strong>Avant</strong> : l&#39;app se ferme (plantage, retour à l&#39;écran d&#39;accueil) ; relancée, <code>PO-EPI-2026-0002</code> est « Reçu en partie » — la réception avait bien été enregistrée</td></tr><tr><td><img src="'+n+'" alt=""></td><td><strong>Après</strong> : même geste sur <code>PO-EPI-2026-0003</code> (champ Cidre actif, clavier ouvert)</td></tr><tr><td><img src="'+d+'" alt=""></td><td><strong>Après</strong> : « Réception de PO-EPI-2026-0003 enregistrée : stock à jour, 1 écart(s) signalé(s) — reliquat attendu », l&#39;app reste ouverte</td></tr></tbody></table><p><strong>Cause</strong> (rapport de plantage du simulateur, <code>EXC_BREAKPOINT</code> : <code>Array._checkSubscript</code> ← <code>Binding&lt;A&gt;.subscript.getter</code> ← <code>LigneReception</code>) : l&#39;écran liait chaque champ <strong>par position</strong> (<code>ForEach($modele.lignes) { $ligne in … }</code>). <code>valider()</code> vide <code>lignes</code> ; le champ actif termine son édition juste après et relit <code>lignes[i]</code> dans une liste vide → accès hors bornes. L&#39;enregistrement est déjà fait à ce moment-là, d&#39;où une réception enregistrée malgré le plantage.</p><p><strong>Correction</strong> (<code>iosApp/PosApp/Achats/ReceptionView.swift</code>) : lignes affichées par identifiant stable, champ <strong>Reçu</strong> et menu d&#39;écart liés par <strong>identifiant de ligne</strong> (<code>quantite(_:)</code>, <code>fixerQuantite(_:_:)</code>, <code>fixerMotif(_:_:)</code> ignorent une ligne disparue), et fin d&#39;édition explicite (<code>@FocusState</code>) avant <strong>Valider</strong>, <strong>Tout reçu</strong> et la confirmation de surplus.</p><p><strong>Même motif ailleurs</strong> : seul <code>FeuilleRetourSansTicketView</code> (retour sans ticket, <code>RetourViews.swift</code>) utilisait aussi <code>ForEach($lignes)</code> avec un champ texte et une suppression par balayage → passé aux liaisons par identifiant (<code>modifierLigne</code>). Vérifiés sans défaut : inventaire (champs liés à des valeurs simples du modèle, pas à une liste), transferts à recevoir (liaisons par <code>productId</code>, garde <code>brouillon == nil</code>), retour avec ticket (tableau de taille fixe, jamais vidé, pas de champ texte), panier.</p><p><strong>Android</strong> (lecture de code + test) : l&#39;écran Compose lie déjà par <code>lineId</code> (<code>items(…, key = lineId)</code>, <code>setQuantity(lineId, …)</code>), pas de plantage possible. Deux écarts corrigés au passage : une saisie arrivée sur une ligne disparue effaçait le message d&#39;erreur affiché (<code>updateLine</code> l&#39;ignore maintenant), et <code>validate()</code> est asynchrone — deux touchers rapides de <strong>Valider</strong> pouvaient enregistrer <strong>deux réceptions</strong> (garde <code>submitting</code>) ; le clavier est fermé (<code>clearFocus</code>) avant la validation, comme sur iOS.</p><h2 id="p3-·-prix-des-tuiles-jamais-tronque" tabindex="-1">P3 · Prix des tuiles jamais tronqué <a class="header-anchor" href="#p3-·-prix-des-tuiles-jamais-tronque" aria-label="Permalink to &quot;P3 · Prix des tuiles jamais tronqué&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+l+'" alt=""></td><td><strong>Avant</strong> (captures du 08/11) : la pastille « Formule » / « Meal deal » était posée PAR-DESSUS le coin bas de la tuile et recouvrait la fin du prix (« 19,9 » en anglais)</td></tr><tr><td><img src="'+c+'" alt=""></td><td><strong>Après</strong>, sur l&#39;iPad (vraie stack) en français, anglais et arabe : prix entier ; la pastille passe sur sa propre ligne quand elle ne tient pas à côté du prix</td></tr><tr><td><img src="'+p+'" alt=""></td><td><strong>Après</strong> : écran de vente iPad en anglais</td></tr><tr><td><img src="'+u+'" alt=""></td><td><strong>Après</strong> : planche rendue par le test <code>TuilesPrixTests</code> (vraie mise en page de <code>PosProductTile</code>) — trois langues, largeurs iPad (≈ 128 pt) et iPhone (≈ 100 pt), police normale et agrandie, avec stock bas et quantité au panier</td></tr></tbody></table><p><strong>Règle</strong> (<code>PosVente.swift</code>, <code>PosProductTile</code>) : la pastille (« Formule », « Variantes ») est dans la ligne du prix, jamais en surimpression ; ordre de repli : prix + stock + pastille → prix + icône de stock + pastille → pastille sur une ligne au-dessus du prix → prix seul (réduit en dernier recours). En grande police, pas de ligne de pastille en plus (le nom garde ses deux lignes ; la pastille reste dans l&#39;étiquette VoiceOver). Le prix des lignes de résultats (recherche sur iPhone) ne se tronque plus non plus (<code>fixedSize</code>).</p><p><strong>Android</strong> : la règle était déjà tenue (prix en premier dans un <code>FlowRow</code>, les pastilles passent à la ligne). Écart de parité corrigé : Android n&#39;affichait <strong>pas</strong> la pastille « Formule » (seulement « Variantes ») sur la grille, les résultats en tuiles et le choix des produits d&#39;une addition (plan de salle) ; elle s&#39;affiche maintenant, avec le libellé partagé <code>CaisseStrings.combo.badge</code> (fr « Formule », en « Meal deal », ar « وجبة »), que l&#39;iOS lit aussi.</p><h2 id="p3-·-une-fenetre-ouverte-suit-le-clair-sombre-en-direct" tabindex="-1">P3 · Une fenêtre ouverte suit le clair / sombre en direct <a class="header-anchor" href="#p3-·-une-fenetre-ouverte-suit-le-clair-sombre-en-direct" aria-label="Permalink to &quot;P3 · Une fenêtre ouverte suit le clair / sombre en direct&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+m+'" alt=""></td><td><strong>Avant</strong> : magasin passé de « Clair » à « Système » (iPad en sombre) pendant que « Ouvrir la session » est ouverte : la caisse passe en sombre, la feuille garde un fond clair avec les textes de la palette sombre</td></tr><tr><td><img src="'+g+'" alt=""></td><td><strong>Après</strong> : même scénario, la feuille passe en sombre en direct</td></tr></tbody></table><p>Constat en reproduisant : une bascule clair / sombre <strong>de l&#39;appareil</strong> en mode Système était déjà suivie en direct par les feuilles ; le défaut venait du changement de <strong>mode du magasin</strong> (forcé → Système) feuille ouverte : <code>.preferredColorScheme</code> qui revient à <code>nil</code> ne retire pas le mode forcé déjà posé sur la présentation. Correction (<code>PosTheme.swift</code>) : le mode est posé sur les <strong>fenêtres</strong> de la scène (<code>overrideUserInterfaceStyle</code>, <code>.unspecified</code> en Système), qui le transmettent à toutes les présentations ; l&#39;apparence réelle est relue sur l&#39;écran au retour en Système. Vérifié aussi : Système + bascule de l&#39;appareil (suivie), mode Sombre forcé + bascule de l&#39;appareil (reste sombre).</p><h2 id="centre-d-aide" tabindex="-1">Centre d&#39;aide <a class="header-anchor" href="#centre-d-aide" aria-label="Permalink to &quot;Centre d&#39;aide&quot;">​</a></h2><ul><li><code>appareil-caisse/faire-une-vente</code> : <code>01-ecran-de-vente</code> (+ sombre) refaites — elles montraient « 19,90 » touché par la pastille.</li><li><code>reglages/apparence</code> : <code>08-mode-systeme</code> refaite (même défaut de prix) ; texte : une fenêtre ouverte change aussi en direct (fr, en, ar). Copie dans <code>../2026-11-08-captures-restantes/04-mode-systeme-clair-sombre.webp</code>.</li><li><code>appareil-caisse/reception-sur-la-caisse</code> : « inutile de fermer le clavier avant de valider » (fr, en, ar).</li></ul><h2 id="reste" tabindex="-1">Reste <a class="header-anchor" href="#reste" aria-label="Permalink to &quot;Reste&quot;">​</a></h2><ul><li>Captures Android non faites (émulateurs réservés à un autre agent) : pastille « Formule » sur la grille Android et réception Android (comportement couvert par <code>ReceptionFlowTest</code>).</li><li>Pas de capture iPhone sur la vraie stack : la largeur iPhone est couverte par la planche <code>08</code> (rendu réel du composant).</li></ul></div>',3)])])}const y=t(v,[["render",f]]);export{q as __pageData,y as default};
